661	        // 末尾换行、首尾空白、0x 前缀、分隔符都是格式错误（长度不符）。
662	        for bad in [
663	            format!("{valid}\n"),
664	            format!(" {valid}"),
665	            format!("{valid} "),
666	            format!("0x{valid}"),
667	            format!("{valid}\r\n"),
668	        ] {
669	            assert!(matches!(
670	                Sha256Digest::from_str(&bad),
671	                Err(ParseDigestError::InvalidLength(_))
672	            ));
673	        }
674	
675	        // 长度恰好 64 但含分隔符：按非法字符处理。
676	        let with_dash = format!("{}-{}", &valid[..31], &valid[32..]);
677	        assert_eq!(with_dash.len(), 64);
678	        assert_eq!(
679	            Sha256Digest::from_str(&with_dash).unwrap_err(),
680	            ParseDigestError::InvalidHexChar(31)
681	        );
682	    }
683	
684	    #[test]
685	    fn parse_error_supports_display_and_error_trait() {
686	        use std::str::FromStr;
687	        let len_err = Sha256Digest::from_str("abc").unwrap_err();
688	        let msg = len_err.to_string();
689	        assert!(msg.contains('3'), "unexpected message: {msg}");
690	        assert!(msg.contains("64"), "unexpected message: {msg}");
691	
692	        let char_err = Sha256Digest::from_str(
693	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b85g",
694	        )
695	        .unwrap_err();
696	        assert!(char_err.to_string().contains("63"));
697	
698	        // 两类错误可按类型区分，且都实现 std::error::Error，可常规传递。
699	        fn assert_error<T: std::error::Error>(_: &T) {}
700	        assert_error(&len_err);
701	        assert_error(&char_err);
702	        assert_ne!(len_err, char_err);
703	        let boxed: Box<dyn std::error::Error> = Box::new(char_err);
704	        assert!(boxed.to_string().contains("63"));
705	    }
