264	    #[test]
265	    fn paths_differing_only_in_undecodable_bytes_reach_their_own_files() {
266	        let dir = TestDir::new("undecodable-pair");
267	        // 两个真实路径只在不可解码字节上不同，损失性显示文字相同。
268	        let first = dir.write_file(&os(b"data_\xff.bin"), b"content of first");
