272	        let display_first = first.as_os_str().to_string_lossy().into_owned();
273	        let display_second = second.as_os_str().to_string_lossy().into_owned();
274	        assert_eq!(display_first, display_second);
275	        assert!(display_first.contains('\u{fffd}'));
276	
277	        // 各自得到对应内容的摘要，不能读到另一个文件。
278	        let hex_first = assert_success(&run_digest(first.as_os_str()));
279	        let hex_second = assert_success(&run_digest(second.as_os_str()));
280	        assert_eq!(
281	            hex_first,
282	            inkseal::digest_reader(&b"content of first"[..])
283	                .unwrap()
284	                .to_hex()
285	        );
286	        assert_eq!(
287	            hex_second,
288	            inkseal::digest_reader(&b"content of second"[..])
289	                .unwrap()
290	                .to_hex()
291	        );
292	        assert_ne!(hex_first, hex_second);
