295	    #[test]
296	    fn missing_undecodable_path_reports_not_found_without_reading_sibling() {
297	        let dir = TestDir::new("undecodable-missing");
298	        // 只创建 \xff 版本；访问 \xfe 版本必须报文件不存在，
299	        // 不能因显示文字相同而误读已有文件。
300	        let existing = dir.write_file(&os(b"data_\xff.bin"), b"existing content");
301	        let missing = dir.path().join(os(b"data_\xfe.bin"));
302	
