    let result = io::stdout()
        .lock()
        .write_all(line)
        .and_then(|()| io::stdout().lock().flush());
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            // 直接写原始字节，不经过任何会 panic 的宏；写提示失败也忽略。
            let _ = writeln!(io::stderr().lock(), "inkseal: unable to write to standard output: {err}");
            let _ = io::stderr().lock().flush();
            ExitCode::FAILURE
        }
    }
}

